() => {
  const tags = document.querySelectorAll('[data-testid="tag-root"]');
  const result = Array.from(tags).map(t => {
    const card = t.closest('[data-testid="product-card-cds"]');
    const title = card?.querySelector('h3')?.textContent || '';
    const partner = card?.querySelector('p')?.textContent || '';
    return { tag: t.textContent.trim(), title, partner };
  });
  return result;
}

() => {
  const tags = document.querySelectorAll('[data-testid="tag-root"]');
  const result = [];
  for (const t of tags) {
    const card = t.closest('[data-testid="product-card-cds"]');
    const title = card?.querySelector('h3')?.textContent || '';
    const partner = card?.querySelector('p')?.textContent || '';
    const ariaLabel = card?.querySelector('a')?.getAttribute('aria-label') || '';
    result.push({ tag: t.textContent.trim(), title, partner, ariaLabel });
  }
  // Also check the cards without tags
  const cards = document.querySelectorAll('[data-testid="product-card-cds"]');
  const cardsInfo = Array.from(cards).map(card => {
    const title = card.querySelector('h3')?.textContent || '';
    const partner = card.querySelector('p')?.textContent || '';
    const tag = card.querySelector('[data-testid="tag-root"]')?.textContent?.trim() || 'NO TAG';
    return { title, partner, tag };
  });
  return { tagsFound: result, allCards: cardsInfo };
}
